563	      lines.push('_（本页可见 ' + items.length + ' 条，共 ' + total + ' 条，其余在其它页；点「商品流量待关注」筛选可看全）_');
564	    }
565	  } else if (typeof total === 'number' && total > 0) {
566	    lines.push('_（当前页未显示具体商品，共 ' + total + ' 条；打开「商品流量待关注」筛选可查看）_');
567	  }
568	  return lines;
569	}
570	
571	// 让 content.js 主动点「商品流量待关注」筛选，捞出这几条被限流的具体商品（productId+name+skc）
572	async function scanWatchViaTab() {
573	  const tab = await getGoodsTab();
574	  if (!tab) return null;
575	  return await sendTabRetry(tab.id, { cmd: 'scanWatchList' }, 3);
576	}
577	
578	// ---------------- 对比 & 告警（按店） ----------------
579	// 按店串行：同一店的多条读数消息（切店时常一秒内来两条）排队逐个处理，
580	// 避免"都读到旧快照各报一次"的竞态导致同一事件重复告警。
581	const alertChains = {};
582	// v15：同一商品冷却期内不重复告警。切店/翻页会让「本页可见 decline 数」在 0↔1 抖动，
583	// 旧版按计数上升触发 → 一切店就再推一次。改成按 productId 去重。
584	const ALERT_COOLDOWN_MS = 6 * 60 * 60 * 1000; // 6 小时
585	function pruneAlertedMap(map, now) {
586	  const out = {};
587	  const keepFor = ALERT_COOLDOWN_MS * 4; // 保留 24h 历史，便于排障
588	  for (const id of Object.keys(map || {})) {
589	    const ts = map[id];
590	    if (typeof ts === 'number' && now - ts < keepFor) out[id] = ts;
591	  }
592	  return out;
593	}
594	// 从 items 里挑出冷却期外、尚未报过的新 productId
595	function pickFreshItems(items, alertedMap, now) {
596	  const fresh = [];
597	  const seen = {};
598	  for (const it of items || []) {
599	    if (!it || !it.productId) continue;
600	    const pid = String(it.productId);
601	    if (seen[pid]) continue;
602	    seen[pid] = true;
603	    const last = alertedMap && alertedMap[pid];
604	    if (typeof last === 'number' && now - last < ALERT_COOLDOWN_MS) continue;
605	    fresh.push(it);
606	  }
607	  return fresh;
608	}
609	function markAlerted(alertedMap, items, now) {
610	  const out = Object.assign({}, alertedMap || {});
611	  for (const it of items || []) {
612	    if (it && it.productId) out[String(it.productId)] = now;
613	  }
614	  return out;
615	}
616	function diffAndAlert(name) {
617	  const prev = alertChains[name] || Promise.resolve();
618	  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
619	  alertChains[name] = next;
620	  return next;
621	}
622	
623	async function _diffAndAlert(name) {
624	  const cfg = await getConfig();
625	  if (!cfg.enabled) return;
626	  const stores = await getStores();
627	  const s = stores[name];
628	  if (!s) return;
629	  let latest = s.latest || {};
630	  const snap = s.snapshot || {};
631	  const now = Date.now();
632	  // v16：统一用 alertedTrafficIds（兼容读旧 alertedWatch/Decline）
633	  let alerted = pruneAlertedMap(
634	    Object.assign({}, snap.alertedWatchIds || {}, snap.alertedDeclineIds || {}, snap.alertedTrafficIds || {}),
635	    now
636	  );
637	
638	  // 在售数量下降：v14 起关闭
639	  // ---- 限流池（在售 ∩ 待关注/下降）分级 ----
640	  // chip 上升时主动扫一次，把明细并进 latest 再分级
641	  const watchCountUp = typeof snap.trafficWatch === 'number'
642	    && typeof latest.trafficWatch === 'number'
643	    && latest.trafficWatch > snap.trafficWatch;
644	  if (watchCountUp) {
645	    const scan = await scanWatchViaTab();
646	    if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
647	      const mergedWatch = {};
648	      for (const it of (latest.watchItems || []).concat(scan.items)) {
649	        if (it && it.productId) mergedWatch[String(it.productId)] = it;
650	      }
651	      latest = Object.assign({}, latest, { watchItems: Object.keys(mergedWatch).map((k) => mergedWatch[k]) });
652	      await updateStoreLatest(name, { watchItems: latest.watchItems });
653	    }
654	  }
655	
656	  const pool = buildTrafficPool(latest);
657	  const baselineReady = !!snap.alertedTrafficIds || !!snap.alertedWatchIds || !!snap.alertedDeclineIds
658	    || typeof snap.trafficWatch === 'number';
659	
660	  let fresh = [];
661	  if (!baselineReady) {
662	    // 首次 / 升级：只 seed，不告警
663	    alerted = markAlerted(alerted, pool, now);
