139	    if (/已下架|已终止|已删除|下架\/已终止/.test(t)) return 'removed';
140	    if (/(^|[^一-鿿])在售([^一-鿿]|$)/.test(t) || /在售中/.test(t)) return 'onSale';
141	    // 列表「商品信息」格常见单独的「在售」小标签
142	    if (/\b在售\b/.test(t) || /在售/.test(t)) return 'onSale';
143	    return 'unknown';
