145	  // 从表格行抽 SKU 货号：列文本多为 JMCAT* / VIP* 短码；也兼容「货号：XXX」
146	  function extractSkuCodesFromText(text) {
147	    const t = String(text || '');
148	    const codes = [];
149	    const seen = {};
150	    const push = (c) => {
151	      const s = String(c || '').trim();
152	      if (!s || s.length < 2 || s.length > 40) return;
153	      if (/^(SPU|SKC|SKU|ID|USD|CNY)$/i.test(s)) return;
154	      const key = s.toUpperCase();
155	      if (seen[key]) return;
156	      seen[key] = true;
157	      codes.push(s);
158	    };
159	    // 货号：XXX / 货号:XXX
160	    let m;
