162	    while ((m = reLabeled.exec(t))) push(m[1]);
163	    // 独立 token：VIP* / JM*（及一般货号字母数字）
164	    const reToken = /\b((?:VIP|JM)[A-Za-z0-9_\-]{0,30}|[A-Z]{2,}[A-Z0-9_\-]{2,})\b/g;
165	    while ((m = reToken.exec(t))) {
166	      // 排除明显非货号
167	      if (/^(SPU|SKC|SKU|USD|CNY|NEW|BETA)$/i.test(m[1])) continue;
168	      push(m[1]);
169	    }
170	    return codes;
171	  }
