187	      if (!raw || raw.length > 80) continue;
188	      if (/SPU\s*ID|商品流量|热销款|申报价格|创建时间/.test(raw)) continue;
189	      // 短单元格更像货号列
190	      if (raw.length <= 48 && /[A-Za-z]/.test(raw) && !/[一-鿿]/.test(raw)) {
191	        add(extractSkuCodesFromText(raw));
192	      }
193	    }
194	    // 兜底整行
195	    if (!codes.length) add(extractSkuCodesFromText(tr.textContent || ''));
196	    return codes;
