function extractSkuCodesFromText(text) {
  const t = String(text || '');
  const codes = [];
  const seen = {};
  const push = (c) => {
    const s = String(c || '').trim();
    if (!s || s.length < 2 || s.length > 40) return;
    if (/^(SPU|SKC|SKU|ID|USD|CNY)$/i.test(s)) return;
    const key = s.toUpperCase();
    if (seen[key]) return;
    seen[key] = true;
    codes.push(s);
  };
