  const add = (arr) => {
    for (const c of arr || []) {
      const k = String(c).toUpperCase();
      if (seen[k]) continue;
      seen[k] = true;
      codes.push(c);
    }
  };
  // 优先「SKU货号」列：找只含货号、不含 SPU/中文长标题的 td
  const tds = [...tr.querySelectorAll('td')];
  for (const td of tds) {
    const raw = (td.textContent || '').trim();
    if (!raw || raw.length > 80) continue;
    if (/SPU\s*ID|商品流量|热销款|申报价格|创建时间/.test(raw)) continue;
