893	const FAKE_STORE_WORDS = /^(black|white|grey|gray|beige|brown|charcoal|red|blue|green|pink|purple|yellow|orange|gold|silver|ivory|cream|navy|olive|tan|khaki|maroon|coral|mint|teal|cyan|magenta|wine|rose|nude|camel|sand|stone|rustic|dark|light|natural|clear|multi|assorted|random|one size|os|xs|s|m|l|xl|xxl|xxxl|sku|skc|spu|usd|cny|eur|gbp|new|beta|seller|central|best|english|chinese|all|more|less|edit|save|submit|cancel|close|next|prev|back|home|cart|account|login|sign|menu|search|help|support|local|warehouse|free|shipping|sale|off|pack|size|color|colour|style|qty|quantity|option|select)$/i;
894	function isFakeStoreName(t) {
895	  if (!t) return true;
896	  const s = String(t).trim();
897	  if (s.length < 2 || s.length > 30) return true;
898	  if (/^[A-Z0-9]+$/.test(s)) return true;
899	  if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller|当前店铺)$/i.test(s)) return true;
900	  const words = s.split(/\s+/);
901	  if (words.every((w) => FAKE_STORE_WORDS.test(w))) return true;
902	  if (words.length === 1 && FAKE_STORE_WORDS.test(words[0])) return true;
