249	function parseHHMM(s) {
250	  const m = String(s || '').trim().match(/^(\d{1,2})[:.：](\d{2})$/);
251	  if (!m) return null;
252	  const h = Number(m[1]);
253	  const min = Number(m[2]);
254	  if (h > 23 || min > 59) return null;
255	  return { h, min, label: String(h).padStart(2, '0') + ':' + String(min).padStart(2, '0') };
256	}
257	// 下一次触发时间戳（本地时区）；若今天该时刻已过（或 5 秒内），排到明天
258	function nextWhen(hhmm) {
259	  const p = parseHHMM(hhmm);
260	  if (!p) return null;
261	  const now = new Date();
262	  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), p.h, p.min, 0, 0);
263	  if (t.getTime() <= now.getTime() + 5000) t.setDate(t.getDate() + 1);
264	  return t.getTime();
265	}
