async function _diffAndAlert(name) {
  const cfg = await getConfig();
  if (!cfg.enabled) return;
  const stores = await getStores();
  const s = stores[name];
  if (!s) return;
  let latest = s.latest || {};
  const snap = s.snapshot || {};
  const now = Date.now();
  // v16：统一用 alertedTrafficIds（兼容读旧 alertedWatch/Decline）
  let alerted = pruneAlertedMap(
    Object.assign({}, snap.alertedWatchIds || {}, snap.alertedDeclineIds || {}, snap.alertedTrafficIds || {}),
    now
  );

  // 在售数量下降：v14 起关闭
  // ---- 限流池（在售 ∩ 待关注/下降）分级 ----
  // chip 上升时主动扫一次，把明细并进 latest 再分级
  const watchCountUp = typeof snap.trafficWatch === 'number'
    && typeof latest.trafficWatch === 'number'
    && latest.trafficWatch > snap.trafficWatch;
  if (watchCountUp) {
    const scan = await scanWatchViaTab();
    if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
      const mergedWatch = {};
      for (const it of (latest.watchItems || []).concat(scan.items)) {
        if (it && it.productId) mergedWatch[String(it.productId)] = it;
      }
      latest = Object.assign({}, latest, { watchItems: Object.keys(mergedWatch).map((k) => mergedWatch[k]) });
      await updateStoreLatest(name, { watchItems: latest.watchItems });
    }
  }

  const pool = buildTrafficPool(latest);
  const baselineReady = !!snap.alertedTrafficIds || !!snap.alertedWatchIds || !!snap.alertedDeclineIds
    || typeof snap.trafficWatch === 'number';

  let fresh = [];
  if (!baselineReady) {
    // 首次 / 升级：只 seed，不告警
    alerted = markAlerted(alerted, pool, now);
    log.info('Traffic baseline seeded: store=' + name + ' known=' + Object.keys(alerted).length
      + ' pool=' + pool.length);
  } else {
    fresh = pickFreshItems(pool, alerted, now);
    // 冷却内但等级从 general→severe 的，也要再报一次（升级）
    for (const it of pool) {
      if (!it || it.severity !== 'severe') continue;
      const pid = String(it.productId);
      if (fresh.some((f) => String(f.productId) === pid)) continue;
      const prevSev = (snap.trafficSeverityMap && snap.trafficSeverityMap[pid]) || '';
      if (prevSev && prevSev !== 'severe') {
        // 升级：无视冷却
        fresh.push(it);
      }
    }
    if (fresh.length) {
      alerted = markAlerted(alerted, fresh, now);
      const severe = fresh.filter((i) => i.severity === 'severe');
      const general = fresh.filter((i) => i.severity !== 'severe');
      const lines = ['**🏬 ' + name + '**'];
      if (severe.length) {
        lines.push('**🔴 严重限流 ' + severe.length + ' 个**（自有VIP / 黑猫JM+热销款）');
        lines.push(...itemLines(severe, severe.length));
      }
      if (general.length) {
        lines.push('**🟠 一般限流 ' + general.length + ' 个**');
        lines.push(...itemLines(general, general.length));
      }
      lines.push('', '_检查时间：' + new Date().toLocaleString('zh-CN') + '_');
      const template = severe.length ? 'red' : 'orange';
      log.info('Alert triggered: store=' + name + ' severe=' + severe.length + ' general=' + general.length);
