          lines.push('解除/不再见 **' + removed.length + '**：');
          for (const it of removed.slice(0, 8)) {
            lines.push('• ~~' + String(it.name || it.productId).slice(0, 28) + '~~  SKC ' + (it.skc || '-'));
          }

