function diffAndAlert(name) {
  const prev = alertChains[name] || Promise.resolve();
  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
  alertChains[name] = next;
  return next;
}

async function _diffAndAlert(name) {
  const cfg = await getConfig();
  if (!cfg.enabled) return;

  // 先在串行锁外做主动扫（可能点 tab，耗时长），避免长时间占住 stores 队列
  let preScanItems = null;
  {
    const storesPeek = await getStores();
    const sPeek = storesPeek[name];
    if (!sPeek) return;
    const latestPeek = sPeek.latest || {};
    const snapPeek = sPeek.snapshot || {};
    const watchCountUpPeek = typeof snapPeek.trafficWatch === 'number'
      && typeof latestPeek.trafficWatch === 'number'
      && latestPeek.trafficWatch > snapPeek.trafficWatch;
    if (watchCountUpPeek) {
      const scan = await scanWatchViaTab();
      if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
        preScanItems = scan.items;
      }
    }
  }

  // 读 latest + 判定 + 写 snapshot 整段串行，杜绝与 updateStoreLatest 交叉覆盖
  const result = await withStores(async () => {
    const stores = await getStores();
    const s = stores[name];
    if (!s) return null;
    let latest = s.latest || {};
    const snap = s.snapshot || {};
    const now = Date.now();
    // v16：统一用 alertedTrafficIds（兼容读旧 alertedWatch/Decline）
    let alerted = pruneAlertedMap(
      Object.assign({}, snap.alertedWatchIds || {}, snap.alertedDeclineIds || {}, snap.alertedTrafficIds || {}),
      now
    );

    // 在售数量下降：v14 起关闭
    // ---- 限流池（在售 ∩ 待关注/下降）分级 ----
    const watchCountUp = typeof snap.trafficWatch === 'number'
      && typeof latest.trafficWatch === 'number'
      && latest.trafficWatch > snap.trafficWatch;

    // 合并主动扫明细进 latest（同一锁内写回，防止丢失）
    if (preScanItems && preScanItems.length) {
      const mergedWatch = {};
      for (const it of (latest.watchItems || []).concat(preScanItems)) {
        if (it && it.productId) mergedWatch[String(it.productId)] = it;
      }
      latest = Object.assign({}, latest, { watchItems: Object.keys(mergedWatch).map((k) => mergedWatch[k]), ts: Date.now() });
      s.latest = latest;
    }

    // 合并：若本轮 items 为空但上次 latest 仍有同店明细，保留旧明细
    // （切店瞬间表格未渲染完会先上报空数组，不能用空覆盖已有限流清单）
    // 注意：这里 latest 已是 storage 最新值；chipStats 侧也会做 merge。

    const pool = buildTrafficPool(latest);
    // v17：基线 = 已 seed 过至少一次有效 alerted ID，或显式 trafficBaselineAt。
    // 旧逻辑把空 {} / 仅 trafficWatch 数字也当 ready → 切店后全量当「新增」误报。
    const baselineReady = hasTrafficBaseline(snap);

    let fresh = [];
    let seeded = false;
    if (!baselineReady) {
      // 首次只 seed 不告警。pool 为空时不建基线（等表格渲染出明细再 seed），
      // 否则空 seed + trafficBaselineAt 会让稍后出现的同一批商品全量误报。
      if (pool.length > 0) {
        alerted = markAlerted(alerted, pool, now);
        seeded = true;
        log.info('Traffic baseline seeded: store=' + name + ' known=' + Object.keys(alerted).length
          + ' pool=' + pool.length);
      } else {
        log.info('Traffic baseline deferred: store=' + name + ' pool empty (wait items)');
      }
    } else {
      fresh = pickFreshItems(pool, alerted, now);
      // 冷却内但等级从 general→severe 的，也要再报一次（升级）
      for (const it of pool) {
        if (!it || it.severity !== 'severe') continue;
        const pid = String(it.productId);
        if (fresh.some((f) => String(f.productId) === pid)) continue;
        const prevSev = (snap.trafficSeverityMap && snap.trafficSeverityMap[pid]) || '';
        if (prevSev && prevSev !== 'severe') {
          fresh.push(it);
        }
      }
      if (fresh.length) {
        alerted = markAlerted(alerted, fresh, now);
      } else if (watchCountUp) {
        log.info('Watch chip rose but no fresh traffic items: store=' + name
          + ' chip=' + snap.trafficWatch + '→' + latest.trafficWatch + ' pool=' + pool.length);
      }

