615	const alertChains = {};
616	// v15：同一商品冷却期内不重复告警。切店/翻页会让「本页可见 decline 数」在 0↔1 抖动，
617	// 旧版按计数上升触发 → 一切店就再推一次。改成按 productId 去重。
618	const ALERT_COOLDOWN_MS = 6 * 60 * 60 * 1000; // 6 小时
619	function pruneAlertedMap(map, now) {
620	  const out = {};
621	  const keepFor = ALERT_COOLDOWN_MS * 4; // 保留 24h 历史，便于排障
622	  for (const id of Object.keys(map || {})) {
623	    const ts = map[id];
624	    if (typeof ts === 'number' && now - ts < keepFor) out[id] = ts;
625	  }
626	  return out;
627	}
628	// 从 items 里挑出冷却期外、尚未报过的新 productId
629	function pickFreshItems(items, alertedMap, now) {
630	  const fresh = [];
631	  const seen = {};
632	  for (const it of items || []) {
633	    if (!it || !it.productId) continue;
634	    const pid = String(it.productId);
635	    if (seen[pid]) continue;
636	    seen[pid] = true;
637	    const last = alertedMap && alertedMap[pid];
638	    if (typeof last === 'number' && now - last < ALERT_COOLDOWN_MS) continue;
639	    fresh.push(it);
640	  }
641	  return fresh;
642	}
643	function markAlerted(alertedMap, items, now) {
644	  const out = Object.assign({}, alertedMap || {});
645	  for (const it of items || []) {
646	    if (it && it.productId) out[String(it.productId)] = now;
647	  }
648	  return out;
649	}
650	function diffAndAlert(name) {
651	  const prev = alertChains[name] || Promise.resolve();
652	  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
653	  alertChains[name] = next;
654	  return next;
655	}
656	
657	async function _diffAndAlert(name) {
658	  const cfg = await getConfig();
659	  if (!cfg.enabled) return;
660	
661	  // 先在串行锁外做主动扫（可能点 tab，耗时长），避免长时间占住 stores 队列
662	  let preScanItems = null;
663	  {
664	    const storesPeek = await getStores();
665	    const sPeek = storesPeek[name];
666	    if (!sPeek) return;
667	    const latestPeek = sPeek.latest || {};
668	    const snapPeek = sPeek.snapshot || {};
669	    const watchCountUpPeek = typeof snapPeek.trafficWatch === 'number'
670	      && typeof latestPeek.trafficWatch === 'number'
671	      && latestPeek.trafficWatch > snapPeek.trafficWatch;
672	    if (watchCountUpPeek) {
673	      const scan = await scanWatchViaTab();
674	      if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
675	        preScanItems = scan.items;
676	      }
677	    }
678	  }
679	
680	  // 读 latest + 判定 + 写 snapshot 整段串行，杜绝与 updateStoreLatest 交叉覆盖
681	  const result = await withStores(async () => {
682	    const stores = await getStores();
683	    const s = stores[name];
684	    if (!s) return null;
685	    let latest = s.latest || {};
686	    const snap = s.snapshot || {};
687	    const now = Date.now();
688	    // v16：统一用 alertedTrafficIds（兼容读旧 alertedWatch/Decline）
689	    let alerted = pruneAlertedMap(
690	      Object.assign({}, snap.alertedWatchIds || {}, snap.alertedDeclineIds || {}, snap.alertedTrafficIds || {}),
691	      now
692	    );
693	
694	    // 在售数量下降：v14 起关闭
695	    // ---- 限流池（在售 ∩ 待关注/下降）分级 ----
696	    const watchCountUp = typeof snap.trafficWatch === 'number'
697	      && typeof latest.trafficWatch === 'number'
698	      && latest.trafficWatch > snap.trafficWatch;
699	
700	    // 合并主动扫明细进 latest（同一锁内写回，防止丢失）
701	    if (preScanItems && preScanItems.length) {
702	      const mergedWatch = {};
703	      for (const it of (latest.watchItems || []).concat(preScanItems)) {
704	        if (it && it.productId) mergedWatch[String(it.productId)] = it;
705	      }
706	      latest = Object.assign({}, latest, { watchItems: Object.keys(mergedWatch).map((k) => mergedWatch[k]), ts: Date.now() });
707	      s.latest = latest;
708	    }
709	
710	    // 合并：若本轮 items 为空但上次 latest 仍有同店明细，保留旧明细
711	    // （切店瞬间表格未渲染完会先上报空数组，不能用空覆盖已有限流清单）
712	    // 注意：这里 latest 已是 storage 最新值；chipStats 侧也会做 merge。
713	
714	    const pool = buildTrafficPool(latest);
715	    // v17：基线 = 已 seed 过至少一次有效 alerted ID，或显式 trafficBaselineAt。
716	    // 旧逻辑把空 {} / 仅 trafficWatch 数字也当 ready → 切店后全量当「新增」误报。
717	    const baselineReady = hasTrafficBaseline(snap);
718	
719	    let fresh = [];
720	    let seeded = false;
721	    if (!baselineReady) {
722	      // 首次只 seed 不告警。pool 为空时不建基线（等表格渲染出明细再 seed），
723	      // 否则空 seed + trafficBaselineAt 会让稍后出现的同一批商品全量误报。
724	      if (pool.length > 0) {
725	        alerted = markAlerted(alerted, pool, now);
726	        seeded = true;
727	        log.info('Traffic baseline seeded: store=' + name + ' known=' + Object.keys(alerted).length
728	          + ' pool=' + pool.length);
729	      } else {
730	        log.info('Traffic baseline deferred: store=' + name + ' pool empty (wait items)');
731	      }
732	    } else {
733	      fresh = pickFreshItems(pool, alerted, now);
734	      // 冷却内但等级从 general→severe 的，也要再报一次（升级）
735	      for (const it of pool) {
736	        if (!it || it.severity !== 'severe') continue;
737	        const pid = String(it.productId);
738	        if (fresh.some((f) => String(f.productId) === pid)) continue;
739	        const prevSev = (snap.trafficSeverityMap && snap.trafficSeverityMap[pid]) || '';
740	        if (prevSev && prevSev !== 'severe') {
741	          fresh.push(it);
742	        }
743	      }
744	      if (fresh.length) {
745	        alerted = markAlerted(alerted, fresh, now);
746	      } else if (watchCountUp) {
747	        log.info('Watch chip rose but no fresh traffic items: store=' + name
748	          + ' chip=' + snap.trafficWatch + '→' + latest.trafficWatch + ' pool=' + pool.length);
749	      }
750	    }
751	
752	    // 写回快照（同一锁内，latest 若被合并也一起存）
753	    const newSnap = Object.assign({}, snap);
754	    if (typeof latest.onSale === 'number') newSnap.onSale = latest.onSale;
755	    if (typeof latest.total === 'number') newSnap.total = latest.total;
756	    if (typeof latest.trafficWatch === 'number') newSnap.trafficWatch = latest.trafficWatch;
757	    if (typeof latest.trafficDecline === 'number') newSnap.trafficDecline = latest.trafficDecline;
758	    newSnap.alertedTrafficIds = alerted;
