      nextAlerted = markAlerted(nextAlerted, pool, now);
      seeded = true;
    }
    return { fresh, nextAlerted, silenced, seeded, chipReallyUp, high: Math.max(prevHigh, curWatch || 0) };
  }

  fresh = pickFreshItems(pool, nextAlerted, now);
  if (fresh.length && !chipReallyUp) {
    silenced = fresh.length;
    nextAlerted = markAlerted(nextAlerted, fresh, now);
    fresh = [];
  }
  if (fresh.length) nextAlerted = markAlerted(nextAlerted, fresh, now);
  // 见过的都记入
  nextAlerted = markAlerted(nextAlerted, pool, now);
  return { fresh, nextAlerted, silenced, seeded, chipReallyUp, high: Math.max(prevHigh, curWatch || 0) };
}

function assert(cond, msg) {
  if (!cond) throw new Error('FAIL: ' + msg);
  console.log('OK  ' + msg);
}

const now = Date.now();
const items = [
  { productId: '111', name: 'A', severity: 'general' },
