Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$src = 'E:\project\temu\temu-plugin'
$zipPath = 'E:\project\temu\temu-plugin-v18-切店静默吸收.zip'
$files = @(
  'manifest.json','background.js','content.js','content-front.js','inject.js',
  'logger.js','feishuApp.js','popup.html','popup.js','options.html','options.js','使用说明.txt'
)
if (Test-Path -LiteralPath $zipPath) { [System.IO.File]::Delete($zipPath) }
$fs = [System.IO.File]::Open($zipPath, [System.IO.FileMode]::CreateNew)
try {
  $zip = New-Object System.IO.Compression.ZipArchive($fs, [System.IO.Compression.ZipArchiveMode]::Create)
  try {
    foreach ($f in $files) {
      $full = Join-Path $src $f
      if (-not (Test-Path -LiteralPath $full)) { throw "missing $f" }
      [System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $full, $f, [System.IO.Compression.CompressionLevel]::Optimal) | Out-Null
    }
  } finally { $zip.Dispose() }
} finally { $fs.Dispose() }
$z2 = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
try { $names = @($z2.Entries | ForEach-Object { $_.FullName }) } finally { $z2.Dispose() }
$manifest = Get-Content -LiteralPath (Join-Path $src 'manifest.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$bg = Select-String -LiteralPath (Join-Path $src 'background.js') -Pattern "bgVersion:\s*'([^']+)'" | Select-Object -First 1
Write-Output ("ZIP=" + $zipPath)
Write-Output ("SIZE=" + (Get-Item -LiteralPath $zipPath).Length)
Write-Output ("manifest=" + $manifest.version)
Write-Output ("bg=" + $bg.Matches[0].Groups[1].Value)
Write-Output ("count=" + $names.Count)
$names | ForEach-Object { Write-Output ("  " + $_) }
